import{_ as e,o as r,c as i,a2 as a}from"./chunks/framework.RQXGjTIX.js";const p=JSON.parse('{"title":"这是什么","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),d={name:"guide/introduction.md"};function n(l,t,o,s,g,c){return r(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h1><p><strong>Applied Crafted Energistics（应用机巧能源，简称 ACE）</strong> 是一个 <strong>非官方</strong>的 <a href="https://modrinth.com/mod/ae2" target="_blank" rel="noreferrer">应用能源 2（AE2）</a> 附属模组，把 <strong>Create: Crafted Beginning（机械动力：机巧新生，CCB）</strong> 的气体接入 ME 网络。</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>支持的 MC 版本</td><td>1.21.1</td></tr><tr><td>加载器</td><td>NeoForge 21.1.251+</td></tr><tr><td>前置</td><td>AE2 19.2.x、Create 6.0.10.x、Create: Crafted Beginning 0.1.x</td></tr><tr><td>可选前置</td><td>MEGA Cells 4.11.x（仅 1M–256M 元件默认配方）</td></tr><tr><td>当前版本</td><td>0.2.2</td></tr><tr><td>源码</td><td><a href="https://github.com/DaKang233/AppliedCraftedEnergistics" target="_blank" rel="noreferrer">GitHub</a></td></tr></tbody></table><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><ul><li><strong>气体存储元件</strong>：1k / 4k / 16k / 64k / 256k / 1M / 4M / 16M / 64M / 256M； 按 <code>1 AE byte = 1,000 GU</code> 计量；</li><li><strong>ME 气体接口</strong>：九组配置/缓存槽，逐槽目标数量、目标压力与传输模式，装有安全卡时过压真实排气；</li><li><strong>气体 P2P 隧道</strong>：把一段气体管路“瞬移”到网络的另一头；</li><li><strong>原生设备互通</strong>：AE2 的输入 / 输出 / 存储总线、ME 接口、样板供应器无需改装即可处理气体；</li><li><strong>升级卡</strong>：元件有 AE2 原生卡 + 四张气体卡；接口有逐槽控制卡与安全卡；总线有气体压力卡；</li><li><strong>JEI 样板编码</strong>：安装 AE2-JEI-Integration 时，JEI 的 “+” 可把 CCB 气体编码进 AE2 处理样板；</li><li><strong>GuideME 游戏内教程</strong>：中英双语，鼠标悬停在气体元件上按 <code>G</code> 打开对应页面。</li></ul><p>1M–256M 元件的默认配方以 <strong>MEGA Cells</strong> 为可选前置；不安装 MEGA 时这些元件仍注册， 但默认生存配方不加载。可通过配置或数据包调整，见 <a href="/appliedcraftedenergistics/guide/config.html">配置文件</a>。</p><h2 id="一句话理解-气体与-me-的关系" tabindex="-1">一句话理解“气体与 ME”的关系 <a class="header-anchor" href="#一句话理解-气体与-me-的关系" aria-label="Permalink to &quot;一句话理解“气体与 ME”的关系&quot;">​</a></h2><p>AE2 网络只认“<strong>数量</strong>”，而 CCB 的气体由“<strong>数量 + 体积 + 气压</strong>”共同描述。 本模组的做法是：</p><ol><li>元件里只保存气体数量（GU），不保存压力；</li><li>任何一次“网络 ↔ 真实世界”的交换，都经过一只<strong>真实的气体容器</strong>（接口的缓冲罐、P2P 的缓冲罐）， 由 CCB 自己的管路求解器负责压力；</li><li>于是 ME 网络永远不会“凭空产生压力”，也不会把玩家的储罐压爆。</li></ol><p>具体换算见 <a href="/appliedcraftedenergistics/guide/pressure.html">气压与容量换算</a>。</p><h2 id="从哪里开始" tabindex="-1">从哪里开始 <a class="header-anchor" href="#从哪里开始" aria-label="Permalink to &quot;从哪里开始&quot;">​</a></h2><ul><li>第一次使用：阅读 <a href="/appliedcraftedenergistics/guide/install.html">安装与版本</a>；</li><li>想快速存气：阅读 <a href="/appliedcraftedenergistics/guide/cells.html">气体存储元件</a>；</li><li>想接入工厂：阅读 <a href="/appliedcraftedenergistics/guide/interface.html">ME 气体接口</a> 与 <a href="/appliedcraftedenergistics/guide/interop.html">与 AE2 原生设备互通</a>。</li></ul><div class="tip custom-block"><p class="custom-block-title">非官方附属</p><p>本项目与 Applied Energistics 2、Create、Create: Crafted Beginning 的官方团队无隶属关系； 发布遵循各前置模组的许可证要求，详见 <a href="/appliedcraftedenergistics/guide/license.html">许可与第三方声明</a>。</p></div>',13)])])}const f=e(d,[["render",n]]);export{p as __pageData,f as default};
